import '../../data/models/major_model.dart';
import '../../data/models/student_model.dart';
class MajorMatch { const MajorMatch(this.major,this.percentage,this.reasons); final MajorModel major; final double percentage; final List<String> reasons; }
class RecommendationService { List<MajorMatch> rank(StudentModel student,List<MajorModel> majors) { return majors.map((major) { final skills=_overlap(student.skillIds,major.skillIds); final interests=_overlap(student.interestIds,major.interestIds); final academic=student.gpa==null?0.5:(student.gpa!>=major.minimumGpa?1:student.gpa!/major.minimumGpa); final score=((skills*.4)+(interests*.35)+(academic.clamp(0,1)*.25))*100; final reasons=<String>[if(skills>0)'توافق في المهارات المطلوبة',if(interests>0)'توافق مع اهتماماتك',if(academic>=1)'معدلك يحقق المتطلب الأكاديمي']; return MajorMatch(major,score,reasons.isEmpty?['أكمل ملفك للحصول على تحليل أدق']:reasons); }).toList()..sort((a,b)=>b.percentage.compareTo(a.percentage)); } double _overlap(List<String> a,List<String> b)=>b.isEmpty?0:a.where(b.contains).length/b.length; }
